import{_ as o,C as r,o as a,c as i,ag as d,E as c}from"./chunks/framework.cyF4XceO.js";const _=JSON.parse('{"title":"所有範囲","description":"Takoform の各境界を所有する repository と runtime。","frontmatter":{"title":"所有範囲","description":"Takoform の各境界を所有する repository と runtime。"},"headers":[],"relativePath":"ja/docs/ownership.md","filePath":"ja/docs/ownership.md"}'),s={name:"ja/docs/ownership.md"};function n(l,t,m,p,h,f){const e=r("StatusNote");return a(),i("div",null,[t[0]||(t[0]=d('<h1 id="所有範囲" tabindex="-1">所有範囲 <a class="header-anchor" href="#所有範囲" aria-label="Permalink to &quot;所有範囲&quot;">​</a></h1><p>境界ごとに一つの authority を置くことで、Takoform は移植性を保ちます。 Provider は contract を projection できますが、利用する contract 自体の authority にはなりません。</p><table tabindex="0"><thead><tr><th>境界</th><th>所有者</th><th>決めること</th></tr></thead><tbody><tr><td>Normative Specification、schema、conformance、receipt</td><td><a href="https://github.com/tako0614/takoform" target="_blank" rel="noreferrer"><code>takoform</code></a></td><td>Host API の意味、identity grammar、canonicalization、package / trust format、履歴資料。同じ repository が Core <code>v1.1.0</code> を公開します。</td></tr><tr><td>Form family と exact FormRef</td><td><a href="https://github.com/tako0614/takoform-forms" target="_blank" rel="noreferrer"><code>takoform-forms</code></a></td><td>family group、<code>formId</code>、<code>definitionVersion</code>、Form / package bytes、fixture、signature、deprecation、revocation。</td></tr><tr><td>Terraform / OpenTofu Provider</td><td><a href="https://github.com/tako0614/terraform-provider-takoform" target="_blank" rel="noreferrer"><code>terraform-provider-takoform</code></a></td><td>typed resource、state、import の mapping と不変の Provider release 履歴。</td></tr><tr><td>host runtime</td><td>host の operator と実装</td><td>capability support、配置、scaling、資格情報、routing、recovery、billing、quota、SLA、live catalog。</td></tr><tr><td>deployment と secret</td><td>operator</td><td>endpoint、space、資格情報、capacity policy、production state。Form や Provider の公開 metadata にはしません。</td></tr></tbody></table><h2 id="この分担から分かること" tabindex="-1">この分担から分かること <a class="header-anchor" href="#この分担から分かること" aria-label="Permalink to &quot;この分担から分かること&quot;">​</a></h2><ul><li>Provider release は Form を公開せず、Host API lane も変えません。</li><li>Core release は Provider version や Form を選びません。</li><li>Form の意味論を変更するときは、Form publisher が <code>definitionVersion</code> を変更します。</li><li>host は Host Support Profile で、対応する exact FormRef を知らせます。</li><li>このサイトは事実を要約しますが、live capability、資格情報、deployment state は所有しません。</li></ul><p>現行の wire identity は literal な <code>forms.takoform.com/v1</code> です。サイトが <code>/v1.1</code> を作ったり、番号付き Specification receipt を他の所有者の release authority として扱ったりすることはありません。</p><h2 id="source-と履歴" tabindex="-1">source と履歴 <a class="header-anchor" href="#source-と履歴" aria-label="Permalink to &quot;source と履歴&quot;">​</a></h2><p><a href="/ja/docs/versions.html">バージョンモデル</a>に現行 4 stream を、<a href="/ja/spec/">仕様資料（履歴）</a> と<a href="/ja/docs/history.html">リリース資料</a>に保持された source をまとめています。 旧 URL には履歴であることを示す案内があります。</p>',8)),c(e)])}const k=o(s,[["render",n]]);export{_ as __pageData,k as default};
